// Access level; Admin includes Write includes Read.
// Ref: #/components/schemas/Permission
type Permission string

const (
	PermissionRead  Permission = "read"
	PermissionWrite Permission = "write"
	PermissionAdmin Permission = "admin"
)

// AllValues returns all Permission values.
func (Permission) AllValues() []Permission {
	return []Permission{
		PermissionRead,
		PermissionWrite,
		PermissionAdmin,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s Permission) MarshalText() ([]byte, error) {
	switch s {
	case PermissionRead:
		return []byte(s), nil
	case PermissionWrite:
		return []byte(s), nil
	case PermissionAdmin:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *Permission) UnmarshalText(data []byte) error {
	switch Permission(data) {
	case PermissionRead:
		*s = PermissionRead
		return nil
	case PermissionWrite:
		*s = PermissionWrite
		return nil
	case PermissionAdmin:
		*s = PermissionAdmin
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

